<script setup>
import { ref } from 'vue'
import { Sparkles, Send, Plus, Paperclip, Mic, ChevronDown, UserRound, Copy, ThumbsUp, ThumbsDown, CalendarDays, Search, FileText } from 'lucide-vue-next'
const input=ref(''), busy=ref(false), messages=ref([])
const suggestions=['Summarize my day','Find time for a deep work session','Research the latest AI trends']
function send(text=input.value){if(!text.trim())return;messages.value.push({role:'user',text});input.value='';busy.value=true;setTimeout(()=>{messages.value.push({role:'assistant',text:`I can help with that. In this demo, I would check your connected apps and prepare a grounded response for: “${text}”`,tool:'Calendar · Notion'});busy.value=false},700)}
</script>
<template><div class="page chat-page"><header class="page-header chat-header"><div><div class="eyebrow">YOUR PERSONAL ASSISTANT</div><h1>Ask DayWave <span class="online-dot"></span></h1><p class="page-subtitle">Think out loud. I'll help you figure it out.</p></div><button class="secondary-btn"><Sparkles :size="16"/> DayWave model <ChevronDown :size="15"/></button></header><div class="chat-workspace"><div class="chat-messages" :class="{empty:!messages.length}"><div v-if="!messages.length" class="welcome"><div class="welcome-icon"><Sparkles :size="24"/></div><h2>What can I help you with?</h2><p>Ask me to find information, organize your day, or take care of a task.</p><div class="suggestions"><button v-for="s in suggestions" :key="s" @click="send(s)">{{s}} <span>↗</span></button></div></div><div v-for="(m,i) in messages" :key="i" class="message" :class="m.role"><div class="message-avatar"><UserRound v-if="m.role==='user'" :size="16"/><Sparkles v-else :size="16"/></div><div class="message-body"><div class="message-name">{{m.role==='user'?'You':'DayWave'}}</div><p>{{m.text}}</p><div v-if="m.tool" class="tool-chip"><span class="tool-dot"></span> Used {{m.tool}}</div><div v-if="m.role==='assistant'" class="message-actions"><button><Copy :size="14"/></button><button><ThumbsUp :size="14"/></button><button><ThumbsDown :size="14"/></button></div></div></div><div v-if="busy" class="message assistant"><div class="message-avatar"><Sparkles :size="16"/></div><div class="typing"><i></i><i></i><i></i></div></div></div><div class="composer-wrap"><form class="composer" @submit.prevent="send()"><textarea v-model="input" rows="1" placeholder="Message DayWave..." @keydown.enter.exact.prevent="send()"></textarea><div class="composer-bottom"><div class="composer-tools"><button type="button"><Plus :size="17"/></button><button type="button"><Paperclip :size="16"/></button><span class="composer-hint">DayWave can make mistakes. Check important information.</span></div><div class="composer-actions"><button type="button" class="mic-btn"><Mic :size="17"/></button><button class="send-btn" :disabled="!input.trim()||busy"><Send :size="16"/></button></div></div></form></div></div></div></template>